-- Nivel's official card board lists a separate article per printing, even when a
-- reprint keeps its original number. The snapshot includes only product names,
-- collection codes and public article-ID:number pairs from 1,525 official entries.
-- http://nivelarena.co.kr/bbs/board.php?bo_table=cardlists&wr_id=664
-- http://nivelarena.co.kr/bbs/board.php?bo_table=cardlists&wr_id=1291
ALTER TABLE pack ADD COLUMN superseded_by bigint,
    ADD FOREIGN KEY (game_code,superseded_by) REFERENCES pack(game_code,id),
    ADD CHECK (superseded_by IS NULL OR (game_code='NIVEL' AND legacy_key IS NOT NULL
        AND starts_with(legacy_key,'catalog:NIVEL:') AND superseded_by<>id));
CREATE FUNCTION current_catalog_pack(wanted bigint) RETURNS bigint
LANGUAGE sql STABLE STRICT AS $$
    SELECT coalesce((SELECT superseded_by FROM pack WHERE id=wanted),wanted)
$$;
CREATE VIEW visible_catalog_pack AS SELECT * FROM pack WHERE superseded_by IS NULL;

CREATE TEMP TABLE nivel54_product(name text PRIMARY KEY, code text, printings text) ON COMMIT DROP;
