CREATE TEMP TABLE nivel54_card ON COMMIT DROP AS
SELECT c.id,p.id AS old_pack,p.code AS old_code,n.name,n.code
FROM nivel54_product n
CROSS JOIN LATERAL unnest(string_to_array(n.printings,' ')) x(pair)
JOIN card c ON c.legacy_key='catalog:NIVEL:ko:'||split_part(x.pair,':',1)
 AND c.number=split_part(x.pair,':',2)
 AND c.source_url='http://nivelarena.co.kr/bbs/board.php?bo_table=cardlists&wr_id='||split_part(x.pair,':',1)
JOIN feed_source f ON f.id=c.source_id AND f.provider='CATALOG' AND f.source_key='NIVEL' AND f.game_code='NIVEL'
JOIN pack p ON p.id=c.pack_id AND p.game_code='NIVEL' AND starts_with(p.legacy_key,'catalog:NIVEL:')
WHERE c.game_code='NIVEL' AND coalesce(c.specs->>'productName',n.name)=n.name;

-- Retain the established numeric ID for each official product. In databases
-- from before the product labels were recovered, its matching code-only pack
-- can be retained if the board verifies that it contains that product.
CREATE TEMP TABLE nivel54_target ON COMMIT DROP AS
SELECT n.name,n.code,(
    SELECT p.id FROM pack p WHERE p.game_code='NIVEL' AND starts_with(p.legacy_key,'catalog:NIVEL:')
      AND (p.name=n.name OR (p.name=p.code AND p.code=n.code AND EXISTS
          (SELECT FROM nivel54_card c WHERE c.old_pack=p.id AND c.name=n.name)))
    ORDER BY (p.name=n.name) DESC,(p.code IS NOT DISTINCT FROM n.code) DESC,p.id LIMIT 1
) AS target FROM nivel54_product n WHERE EXISTS(SELECT FROM nivel54_card c WHERE c.name=n.name);
INSERT INTO pack(legacy_key,game_code,code,name)
SELECT 'catalog:NIVEL:verified-product:'||encode(sha256(convert_to(name,'UTF8')),'hex'),'NIVEL',code,name
FROM nivel54_target WHERE target IS NULL;
UPDATE nivel54_target t SET target=p.id FROM pack p WHERE t.target IS NULL AND
    p.legacy_key='catalog:NIVEL:verified-product:'||encode(sha256(convert_to(t.name,'UTF8')),'hex');
ALTER TABLE nivel54_target ADD PRIMARY KEY(target);
UPDATE pack p SET name=t.name,code=t.code,edit_version=p.edit_version+1
FROM nivel54_target t WHERE p.id=t.target AND (p.name,p.code) IS DISTINCT FROM (t.name,t.code);

WITH updated AS (
    SELECT c.id,t.target,
      (CASE WHEN c.specs#>'{imageProducts,ko}' IS NULL THEN c.specs
            WHEN t.code IS NULL THEN c.specs#-'{imageProducts,ko}'
            ELSE jsonb_set(c.specs,'{imageProducts,ko}',to_jsonb(t.code)) END)
      || jsonb_build_object('productName',t.name) AS specs
    FROM nivel54_card n JOIN card c ON c.id=n.id JOIN nivel54_target t ON t.name=n.name
)
UPDATE card c SET pack_id=u.target,specs=u.specs,edit_version=c.edit_version+1
FROM updated u WHERE c.id=u.id AND (c.pack_id,c.specs) IS DISTINCT FROM (u.target,u.specs);

-- Preserve old URLs and calendar selections. Empty duplicate rows with no
-- editorial fields become aliases. Unknown products and unrelated cards stay visible.
UPDATE pack p SET superseded_by=t.target,edit_version=p.edit_version+1
FROM nivel54_target t WHERE p.id<>t.target AND p.game_code='NIVEL' AND starts_with(p.legacy_key,'catalog:NIVEL:')
  AND (p.name=t.name OR (p.name=p.code AND p.code=t.code AND EXISTS
      (SELECT FROM nivel54_card c WHERE c.old_pack=p.id AND c.name=t.name)))
  AND p.metadata='{}'::jsonb AND p.release_date IS NULL AND p.release_label IS NULL AND p.banner_key IS NULL
  AND NOT EXISTS(SELECT FROM card c WHERE c.pack_id=p.id)
  AND NOT EXISTS(SELECT FROM nivel54_target canonical WHERE canonical.target=p.id);

CREATE OR REPLACE VIEW catalog_pack_date AS
WITH matches AS (
    SELECT current_catalog_pack(e.selected_pack_id) AS pack_id,e.release_date
    FROM product_release e WHERE e.selected_pack_id IS NOT NULL
    UNION ALL
    SELECT min(p.id),min(e.release_date)
    FROM product_release e JOIN visible_catalog_pack p ON p.game_code=e.game_code
      AND (e.catalog_code IS NOT NULL OR e.catalog_name IS NOT NULL)
      AND (e.catalog_code IS NULL OR upper(p.code)=upper(e.catalog_code))
      AND (e.catalog_name IS NULL OR lower(p.name)=lower(e.catalog_name))
      AND CASE WHEN e.game_code='YUGIOH' AND starts_with(e.product_key,'na-premiere:')
               THEN p.metadata @> '{"wp":true,"sec":true}' ELSE starts_with(p.legacy_key,'catalog:') END
    WHERE NOT e.manual AND e.selected_pack_id IS NULL
    GROUP BY e.id HAVING count(*)=1
), announced AS (
    SELECT pack_id,min(release_date) AS release_date FROM matches GROUP BY pack_id
)
SELECT p.id AS pack_id,p.game_code,coalesce(p.release_date,a.release_date) AS release_date
FROM visible_catalog_pack p LEFT JOIN announced a ON a.pack_id=p.id
WHERE coalesce(p.release_date,a.release_date) IS NOT NULL;
